{
  "fichier": "200073161_reglement_20260212.md",
  "bloc": 1,
  "zones_detectees": [
    {
      "zone": "UXb",
      "hauteur_maximale": {
        "valeur": "15 mètres à l’égout de toiture ou à l’acrotère",
        "condition": "sauf pour les ouvrages, installations et constructions nécessaires au fonctionnement des services publics et les ouvrages publics d’infrastructure (dont ferroviaires), pour lesquels il n’est pas fixé de règle de hauteur",
        "page_source": "83"
      },
      "emprise_au_sol": {
        "valeur": "80% de la superficie du terrain",
        "condition": "sauf pour les ouvrages, installations et constructions nécessaires au fonctionnement des services publics et les ouvrages publics d’infrastructure (dont ferroviaires), pour lesquels il n’est pas fixé de règle d’emprise au sol",
        "page_source": "82"
      },
      "implantation_voies": {
        "regle": "Recul des constructions par rapport aux voies et emprises publiques de 5 mètres minimum ; pour le sous-secteur UXb1 : 25 mètres minimum de l’axe de la RD910 et 5 mètres minimum par rapport aux autres voies et emprises publiques ; pour le sous-secteur UXb3 : 15 mètres minimum par rapport à la RD47 et 7 mètres minimum par rapport aux autres voies et emprises publiques",
        "page_source": "83"
      },
      "implantation_limites": {
        "regle": "Les constructions peuvent être implantées en limites séparatives (sauf en UXa4 où un retrait est imposé) ou en retrait de la limite séparative. En cas d’implantation en retrait, la distance minimale de tout point de la façade au point de la limite séparative le plus rapproché ne doit pas être inférieure à la moitié de la hauteur de la construction (H/2) et à un retrait minimal de 10 mètres en UXb. Pour les ouvrages, installations et constructions nécessaires au fonctionnement des services publics et les ouvrages publics d’infrastructure (dont ferroviaires), il n’est pas fixé de règle d’implantation par rapport aux limites séparatives.",
        "page_source": "84-85"
      },
      "stationnement": {
        "regle": "Le nombre de places de stationnement est apprécié en tenant compte à la fois de la destination de la construction, de la taille du projet, de sa localisation, des conditions de stationnement et de la circulation dans le voisinage. Toute construction ou opération doit comporter un espace couvert destiné au stationnement sécurisé des vélos, aménagé conformément à la règlementation en vigueur.",
        "valeur_pl": "non precisee",
        "valeur_vl": "non precisee",
        "page_source": "89"
      },
      "espaces_verts": {
        "regle": "Au moins 10% de la superficie du terrain doit être en pleine terre et végétalisés. Les aires de stationnement doivent faire l’objet d’un traitement paysager et être végétalisées. Les reculs par rapport aux limites de la zone UX doivent faire l’objet d’aménagements soignés et de plantations participant à la bonne insertion de la zone d’activités dans son environnement.",
        "page_source": "88"
      },
      "destinations": {
        "autorisees": [
          "constructions et installations à usage d’activités économiques : commerces, activités de services et autres activités des secteurs secondaires et tertiaires",
          "constructions et installations nécessaires aux services publics ou d’intérêt collectif",
          "logement des personnes dont la présence permanente est indispensable pour assurer la surveillance des établissements, à condition d’être intégré dans le bâtiment d’activité",
          "aires de stationnement",
          "ouvrages, installations et constructions nécessaires au fonctionnement des services publics et les ouvrages publics d’infrastructure (dont ferroviaires)",
          "aires de stockage des produits issus de l’activité de l’établissement ou nécessaires à celle-ci",
          "dans les sous-secteurs UXb2 et UXb3 : constructions et installations à usage agricole"
        ],
        "interdites": [
          "centrales photovoltaïques au sol (sauf dans les secteurs UXa1 et UXe1)",
          "dans le secteur UXd : aires de stockage des produits issus de l’activité de l’établissement ou nécessaires à celle-ci"
        ],
        "page_source": "79-80"
      },
      "contraintes_particulieres": [
        {
          "description": "Aucun accès direct n’est autorisé sur les routes départementales",
          "page_source": "90"
        },
        {
          "description": "Dans le sous-secteur UXa3, aucun nouvel accès direct n’est autorisé sur la RD976. Les deux accès existants seront autant que nécessaires mutualisés. Ils doivent être aménagés ou restructurés de manière à assurer la sécurité des usagers de la RD976 et celle des usagers des accès eux-mêmes.",
          "page_source": "90"
        },
        {
          "description": "Implantation en limite séparative conditionnée à la bonne réalisation de mesures indispensables à la sécurité, notamment vis-à-vis du risque incendie",
          "page_source": "84"
        },
        {
          "description": "Les constructions à usage d’habitation doivent être intégrées dans le corps du bâtiment d’activités",
          "page_source": "86"
        },
        {
          "description": "Les aires de stockage seront autant que possible incluses dans une construction. Dans le cas contraire, lorsqu’elles ne concernent pas des produits exposés à la vente, elles doivent être le moins visibles possible depuis l’espace public et les terrains mitoyens (murets, haies, implantation sur le terrain, etc.)",
          "page_source": "86"
        },
        {
          "description": "Dans le sous-secteur UXa3, le recul par rapport à la RD976 doit être végétalisé et arboré",
          "page_source": "88"
        },
        {
          "description": "Les clôtures doivent être constituées d’un grillage ou d’un dispositif à claire-voie et doublées d’une haie vive d’essences variées. Sauf dispositions légales ou règlementaires particulières à l’établissement considéré, la hauteur maximale des clôtures est de 2 mètres",
          "page_source": "87"
        },
        {
          "description": "En limite d’une zone A ou N, les clôtures doivent être constituées d’une haie champêtre doublée d’un grillage, d’une grille ou d’un dispositif à claire-voie, en matériaux naturels (bois, etc.)",
          "page_source": "87"
        },
        {
          "description": "Les constructions doivent présenter une unité et une qualité quant aux matériaux et aux teintes utilisées. Une attention particulière sera apportée aux façades donnant sur l’espace public",
          "page_source": "86"
        },
        {
          "description": "Périmètre d’Attente de Projet Global d’Aménagement (PAPAG) pour la zone UXb3 (Étang Vignon à Vouvray) : constructibilité limitée à 50 m² d'emprise au sol d'annexes ou d'extensions pour une durée de 5 ans à compter de la date d’approbation du PLUi",
          "page_source": "210"
        }
      ]
    }
  ],
  "alertes": []
}

